/* ============================================
   ShiftWise — Restaurant Team Management SaaS
   Design System & Global Styles
   ============================================ */

/* ── Imports ───────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');

/* ── CSS Variables ─────────────────────────── */
:root {
  /* Brand Colors */
  --primary: #0051C3;
  --primary-dark: #003d94;
  --primary-light: #e6f0ff;
  --accent: #DE5052;
  --accent-dark: #c23d3f;
  --accent-light: #fdeaea;

  /* Neutrals */
  --navy: #0f1a2e;
  --charcoal: #1e293b;
  --slate: #334155;
  --gray: #64748b;
  --gray-light: #94a3b8;
  --silver: #cbd5e1;
  --cloud: #f1f5f9;
  --snow: #f8fafc;
  --white: #ffffff;

  /* Semantic */
  --background: var(--white);
  --foreground: var(--navy);
  --surface: var(--snow);
  --surface-raised: var(--white);
  --border: var(--silver);
  --muted: var(--gray);

  /* Typography */
  --font-display: 'Space Grotesk', system-ui, sans-serif;
  --font-sans: 'Inter', system-ui, sans-serif;

  /* Spacing Scale (4px base) */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.25rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* ── Reset & Base ──────────────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--foreground);
  background: var(--background);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, textarea, select {
  font-family: inherit;
  font-size: inherit;
}

/* ── Utility Classes ───────────────────────── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding-left: var(--space-5);
  padding-right: var(--space-5);
}

@media (min-width: 768px) {
  .container {
    padding-left: var(--space-8);
    padding-right: var(--space-8);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Typography ────────────────────────────── */
.heading-xl {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.heading-lg {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.heading-md {
  font-family: var(--font-display);
  font-size: clamp(1.25rem, 2.5vw, 1.5rem);
  font-weight: 600;
  line-height: 1.3;
}

.heading-sm {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.4;
}

.body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray);
}

.body-md {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--gray);
}

.body-sm {
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--gray-light);
}

/* ── Buttons ───────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 0.75rem 1.5rem;
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(0);
  box-shadow: var(--shadow-sm);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary-light);
}

.btn-ghost {
  background: transparent;
  color: var(--slate);
}

.btn-ghost:hover {
  background: var(--cloud);
  color: var(--navy);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1rem;
}

/* ── Cards ─────────────────────────────────── */
.card {
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-static {
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
}

/* ── Forms ─────────────────────────────────── */
.form-group {
  margin-bottom: var(--space-5);
}

.form-label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--slate);
  margin-bottom: var(--space-2);
}

.form-input,
.form-textarea,
.form-select {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  color: var(--foreground);
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-textarea:focus,
.form-select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.12);
}

.form-input::placeholder,
.form-textarea::placeholder {
  color: var(--gray-light);
}

.form-textarea {
  min-height: 120px;
  resize: vertical;
}

.form-error {
  font-size: 0.8125rem;
  color: var(--accent);
  margin-top: var(--space-1);
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-group.has-error .form-input,
.form-group.has-error .form-textarea,
.form-group.has-error .form-select {
  border-color: var(--accent);
}

.form-success {
  background: #ecfdf5;
  border: 1px solid #a7f3d0;
  border-radius: var(--radius-md);
  padding: var(--space-5);
  text-align: center;
  display: none;
}

.form-success.is-visible {
  display: block;
}

/* ── Header / Nav ──────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--navy);
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.nav-desktop {
  display: none;
}

.nav-desktop ul {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-desktop a {
  padding: 0.5rem 0.875rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--slate);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-desktop a:hover,
.nav-desktop a.active {
  color: var(--primary);
  background: var(--primary-light);
}

.header-actions {
  display: none;
  align-items: center;
  gap: var(--space-3);
}

.mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: var(--slate);
  border-radius: var(--radius-md);
}

.mobile-toggle:hover {
  background: var(--cloud);
}

@media (min-width: 768px) {
  .nav-desktop { display: flex; }
  .header-actions { display: flex; }
  .mobile-toggle { display: none; }
}

/* ── Mobile Nav Drawer ─────────────────────── */
.mobile-drawer {
  position: fixed;
  inset: 0;
  z-index: 200;
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.mobile-drawer.is-open {
  pointer-events: auto;
  opacity: 1;
}

.drawer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 26, 46, 0.5);
}

.drawer-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: min(320px, 85vw);
  height: 100%;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  display: flex;
  flex-direction: column;
}

.mobile-drawer.is-open .drawer-panel {
  transform: translateX(0);
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) var(--space-5);
  border-bottom: 1px solid var(--border);
}

.drawer-close {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray);
  border-radius: var(--radius-md);
}

.drawer-close:hover {
  background: var(--cloud);
  color: var(--navy);
}

.drawer-nav {
  flex: 1;
  padding: var(--space-4);
  overflow-y: auto;
}

.drawer-nav a {
  display: block;
  padding: var(--space-3) var(--space-4);
  font-size: 1rem;
  font-weight: 500;
  color: var(--slate);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.drawer-nav a:hover,
.drawer-nav a.active {
  color: var(--primary);
  background: var(--primary-light);
}

.drawer-footer {
  padding: var(--space-5);
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

/* ── Hero Section ──────────────────────────── */
.hero {
  position: relative;
  padding: var(--space-16) 0;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0, 81, 195, 0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-bg::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(222, 80, 82, 0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-inner {
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 640px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 0.375rem 0.875rem;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.8125rem;
  font-weight: 600;
  border-radius: 9999px;
  margin-bottom: var(--space-5);
}

.hero-title {
  margin-bottom: var(--space-5);
}

.hero-title span {
  color: var(--primary);
}

.hero-subtitle {
  margin-bottom: var(--space-8);
  max-width: 520px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.hero-visual {
  margin-top: var(--space-12);
}

/* ── Section Utilities ─────────────────────── */
.section {
  padding: var(--space-20) 0;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto var(--space-12);
}

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: var(--space-3);
}

.section-title {
  margin-bottom: var(--space-4);
}

.section-subtitle {
  color: var(--gray);
}

/* ── Feature Cards ─────────────────────────── */
.features-grid {
  display: grid;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .features-grid { grid-template-columns: repeat(3, 1fr); }
}

.feature-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-4);
}

.feature-icon.blue {
  background: var(--primary-light);
  color: var(--primary);
}

.feature-icon.red {
  background: var(--accent-light);
  color: var(--accent);
}

.feature-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.feature-desc {
  font-size: 0.9375rem;
  color: var(--gray);
  line-height: 1.6;
}

/* ── How It Works ──────────────────────────── */
.steps-grid {
  display: grid;
  gap: var(--space-8);
  counter-reset: step;
}

@media (min-width: 768px) {
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .steps-grid { grid-template-columns: repeat(4, 1fr); }
}

.step {
  position: relative;
}

.step-number {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-4);
}

.step-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.step-desc {
  font-size: 0.9375rem;
  color: var(--gray);
  line-height: 1.6;
}

/* ── Testimonials ──────────────────────────── */
.testimonial-section {
  background: var(--navy);
  color: var(--white);
  padding: var(--space-20) 0;
}

.testimonial-section .section-label {
  color: #7aa8ff;
}

.testimonial-section .section-title {
  color: var(--white);
}

.testimonial-section .section-subtitle {
  color: var(--gray-light);
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-track {
  overflow: hidden;
}

.testimonial-slides {
  display: flex;
  transition: transform var(--transition-slow);
}

.testimonial-slide {
  flex: 0 0 100%;
  padding: 0 var(--space-4);
}

.testimonial-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
}

.testimonial-quote {
  font-size: clamp(1.125rem, 2.5vw, 1.5rem);
  font-weight: 500;
  line-height: 1.5;
  margin-bottom: var(--space-6);
  color: var(--white);
}

.testimonial-author {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  color: var(--white);
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-light);
}

.testimonial-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.testimonial-btn {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.testimonial-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}

.testimonial-dots {
  display: flex;
  gap: var(--space-2);
}

.testimonial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  transition: all var(--transition-fast);
}

.testimonial-dot.is-active {
  background: var(--white);
  width: 24px;
  border-radius: 4px;
}

/* ── Stats Banner ──────────────────────────── */
.stats-section {
  padding: var(--space-16) 0;
  background: var(--snow);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
  text-align: center;
}

@media (min-width: 768px) {
  .stats-grid { grid-template-columns: repeat(4, 1fr); }
}

.stat-value {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 700;
  color: var(--primary);
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--gray);
}

/* ── Pricing ───────────────────────────────── */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  margin-bottom: var(--space-10);
}

.toggle-label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--slate);
  transition: color var(--transition-fast);
}

.toggle-label.is-active {
  color: var(--primary);
  font-weight: 600;
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--primary);
  border-radius: 9999px;
  cursor: pointer;
  transition: background var(--transition-fast);
  flex-shrink: 0;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition-base);
}

.toggle-switch.is-annual::after {
  transform: translateX(24px);
}

.toggle-save {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-light);
  padding: 0.125rem 0.5rem;
  border-radius: 9999px;
}

.pricing-grid {
  display: grid;
  gap: var(--space-6);
  max-width: 1000px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .pricing-grid { grid-template-columns: repeat(3, 1fr); }
}

.pricing-card {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.is-featured {
  border-color: var(--primary);
  position: relative;
}

.pricing-card.is-featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.875rem;
  border-radius: 9999px;
}

.pricing-name {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
